#!/usr/bin/env python3
"""Embed a .ttf into a C translation unit for flash-resident TinyTTF."""

from __future__ import annotations

import argparse
from pathlib import Path


def embed(symbol: str, ttf_path: Path, out_path: Path) -> None:
    data = ttf_path.read_bytes()
    lines = [
        "/* Auto-generated by embed_ttf.py — do not edit. */",
        '#include "FontEmbedded.h"',
        "",
        f"const uint8_t font_embedded_{symbol}_data[] = {{",
    ]

    row: list[str] = []
    for byte in data:
        row.append(f"0x{byte:02x}")
        if len(row) == 12:
            lines.append("    " + ", ".join(row) + ",")
            row = []
    if row:
        lines.append("    " + ", ".join(row))
    lines.append("};")
    lines.append("")
    lines.append(f"const size_t font_embedded_{symbol}_size = {len(data)};")
    lines.append("")

    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")


def main() -> None:
    parser = argparse.ArgumentParser(description="Embed TTF as C byte array")
    parser.add_argument("symbol", help="C symbol suffix, e.g. awesome")
    parser.add_argument("input", type=Path, help="Source .ttf path")
    parser.add_argument("output", type=Path, help="Output .c path")
    args = parser.parse_args()
    embed(args.symbol, args.input, args.output)


if __name__ == "__main__":
    main()
